sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    var updates = [{
            table: 'x_hccc_hoc_ohs_h_and_v_negotiated_resolution',
            field: 'negotiated_resolution'
        },
        {
            table: 'x_hccc_hoc_ohs_h_and_v_investigation',
            field: 'investigation'
        },
        {
            table: 'x_hccc_hoc_ohs_h_and_v_mediation',
            field: 'mediation'
        },
        {
            table: 'x_hccc_hoc_ohs_h_and_v_preventative_measures',
            field: 'preventative_meaures'
        },
        {
            table: 'x_hccc_hoc_ohs_h_and_v_initial_review',
            field: 'initial_review'
        },
        {
            table: 'x_hccc_hoc_ohs_h_and_v_rw',
            field: 'rw'
        }


    ];

    for (var i = 0; i < updates.length; i++) {
        var gr = new GlideRecord(updates[i].table.toString());

        gr.setValue('parent_case', current.sys_id);
        gr.insert();
        current.setValue(updates[i].field.toString(), gr.sys_id.toString());
    }


})(current, previous);
